// Generated by scripts/build-production.js from src/motion.js: the runtime without hot reloading or the DevTools hook. Do not edit.
// @zubra/runtime/motion: what `animate` on <zb-if>, <zb-switch> and <zb-each> does, as three
// functions any code can call.
//
// The platform animates an element coming in on its own: `@starting-style` gives a transition
// somewhere to start from, and a CSS animation runs when the element is inserted. What it can't do
// is animate one going out, because a removed element is gone. And a list that reorders jumps,
// because moving an element doesn't transition its position. These fill those two gaps, with CSS
// still deciding how everything looks:
//
//   [data-leaving] { opacity: 0; transition: opacity 150ms; }   (on its way out)
//   .row { --zb-move-duration: 250ms; --zb-move-easing: ease-out; }   (gliding to a new place)
//
// Under `prefers-reduced-motion: reduce`, elements leave at once and lists don't glide.

/** Whether the person has asked for less motion. */
export const reducedMotion = () => !!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;

// An element on its way out: it stays in the document until its animations end.
const LEAVING = Symbol('leaving');
/** Whether `node` is an element on its way out (`leave()` was called on it). */
export const isLeaving = (node) => !!node?.[LEAVING];

/** The animations that will end: CSS transitions and animations, except infinite ones (a spinner). */
function finite(element) {
  if (typeof element.getAnimations !== 'function') return [];
  // getAnimations() brings styles up to date first, so the transitions `data-leaving` starts are here.
  return element.getAnimations({ subtree: true }).filter((animation) => {
    const end = animation.effect?.getComputedTiming?.().endTime;
    return end !== Infinity && animation.playState !== 'finished';
  });
}

/**
 * Lets `nodes` finish their exit before they go. Each element gets the `data-leaving` attribute
 * (and `inert`, so it can't be clicked or focused on the way out); it's removed once the
 * transitions and animations that starts have ended, or at once if there are none. Text, comments,
 * and everything under reduced motion are removed at once.
 *
 * - `float`: take leaving elements out of the flow first, fixed where they are, so what's around
 *   them can move into their space as they go (a list does this).
 *
 * Returns a promise for when every element is gone.
 */
export function leave(nodes, { float = false } = {}) {
  const reduced = reducedMotion();
  const elements = [];
  for (const node of nodes) {
    if (node.nodeType === 1 && !reduced && node.isConnected) elements.push(node);
    else node.remove();
  }
  // Read every position before changing any: floating one element moves the next.
  const places = float ? elements.map(placeOf) : [];
  elements.forEach((element, index) => {
    element[LEAVING] = true;
    if (float) Object.assign(element.style, places[index]);
    element.inert = true;
    element.setAttribute('data-leaving', '');
  });
  return Promise.all(elements.map((element) => {
    const running = finite(element);
    if (!running.length) return element.remove();
    return Promise.allSettled(running.map((animation) => animation.finished)).then(() => element.remove());
  }));
}

/** Where an element is, as styles that hold it there out of the flow. */
function placeOf(element) {
  const { width, height } = element.getBoundingClientRect();
  return {
    position: 'absolute',
    top: `${element.offsetTop}px`,
    left: `${element.offsetLeft}px`,
    width: `${width}px`,
    height: `${height}px`,
    margin: '0',
  };
}

/** A CSS time (`250ms`, `0.3s`) in milliseconds, or null. */
function milliseconds(text) {
  const match = /^\s*(-?[\d.]+)(ms|s)\s*$/.exec(text ?? '');
  if (!match) return null;
  return Number(match[1]) * (match[2] === 's' ? 1000 : 1);
}

/**
 * Runs `change` (which moves `elements` about), then animates each element from where it was to
 * where it is now: First, Last, Invert, Play. Elements added or leaving in `change` aren't moved.
 * How long and how: each element's `--zb-move-duration` (250ms) and `--zb-move-easing` (a quick
 * ease-out), so a theme or one list can change them. A duration of 0, or reduced motion, moves
 * them without animating.
 */
export function glide(elements, change) {
  if (reducedMotion()) return change();
  const before = new Map();
  for (const element of elements) if (element.isConnected) before.set(element, element.getBoundingClientRect());
  const result = change();
  for (const [element, was] of before) {
    if (!element.isConnected || element[LEAVING]) continue;
    const now = element.getBoundingClientRect();
    const x = was.left - now.left;
    const y = was.top - now.top;
    if (!x && !y) continue;
    const style = getComputedStyle(element);
    const duration = milliseconds(style.getPropertyValue('--zb-move-duration')) ?? 250;
    if (duration <= 0) continue;
    element.animate(
      [{ transform: `translate(${x}px, ${y}px)` }, { transform: 'none' }],
      // `add`: on top of whatever transform the element has of its own.
      { duration, easing: style.getPropertyValue('--zb-move-easing').trim() || 'cubic-bezier(0.2, 0, 0, 1)', composite: 'add' },
    );
  }
  return result;
}
